public boolean addSite(Stmt site){
  try {
    InstanceInvokeExpr iie=(InstanceInvokeExpr)site.getInvokeExpr();
    if (iie instanceof SpecialInvokeExpr)   throw new RuntimeException("Can't handle that");
    return receiverToSite.put(iie.getBase(),site);
  } catch (ClassCastException | NullPointerException e) {
    throw new RuntimeException("Unexpected error in addSite: " + e.getMessage(), e);
  }
}
